simd_benchmark_source.source:
#include <immintrin.h>
#include <bit>
#include <cstdint>
#include <cstdio>
#include <vector>
#include <random>
#include <chrono>
#include <limits>
#include <string>
#include <cassert>
#include <cinttypes>
struct Input {std::int64_t a,b,c,d,l,r;};
using I=std::int64_t;using U=std::uint64_t;using Wide=__int128_t;
__attribute__((noinline,target("no-avx512f,no-avx512vl")))
unsigned scalar(const Input& i) {
 auto val=[](I a,I x,I b){return std::bit_cast<I>(U(a)*U(x)+U(b));};
 return unsigned(val(i.a,i.l,i.b)<val(i.c,i.l,i.d)) | (unsigned(val(i.a,i.r,i.b)<val(i.c,i.r,i.d))<<1);
}
__attribute__((noinline,target("avx2,no-avx512f,no-avx512vl")))
unsigned avx2(const Input& i) {
 const __m256i a=_mm256_set_epi64x(i.c,i.c,i.a,i.a);
 const __m256i x=_mm256_set_epi64x(i.r,i.l,i.r,i.l);
 const __m256i b=_mm256_set_epi64x(i.d,i.d,i.b,i.b);
 const __m256i p0=_mm256_mul_epu32(a,x);
 const __m256i p1=_mm256_mul_epu32(_mm256_srli_epi64(a,32),x);
 const __m256i p2=_mm256_mul_epu32(a,_mm256_srli_epi64(x,32));
 const __m256i values=_mm256_add_epi64(_mm256_add_epi64(p0,_mm256_slli_epi64(_mm256_add_epi64(p1,p2),32)),b);
 const __m256i other=_mm256_permute2x128_si256(values,values,1);
 const __m256i better=_mm256_cmpgt_epi64(other,values);
 return unsigned(_mm256_movemask_pd(_mm256_castsi256_pd(better)))&3;
}
bool fits(Wide x){return x>=std::numeric_limits<I>::min() && x<=std::numeric_limits<I>::max();}
unsigned reference(const Input&i){return unsigned(Wide(i.a)*i.l+i.b<Wide(i.c)*i.l+i.d)|(unsigned(Wide(i.a)*i.r+i.b<Wide(i.c)*i.r+i.d)<<1);}
std::vector<Input> make_input(std::size_t n){
 std::mt19937_64 gen(2026102809);std::vector<Input> v;v.reserve(n);
 while(v.size()<n){
  Input i;
  if(v.size()%3==0){i={I(gen()),I(gen()),I(gen()),I(gen()),I(gen()%3)-1,I(gen()%3)-1};}
  else{i={I(gen()%2'000'000'001)-1'000'000'000,I(gen()%2'000'000'000'000'000'001)-1'000'000'000'000'000'000,I(gen()%2'000'000'001)-1'000'000'000,I(gen()%2'000'000'000'000'000'001)-1'000'000'000'000'000'000,I(gen()%2'000'000'001)-1'000'000'000,I(gen()%2'000'000'001)-1'000'000'000};}
  if(i.l>i.r)std::swap(i.l,i.r);
  if(!fits(Wide(i.a)*i.l+i.b)||!fits(Wide(i.a)*i.r+i.b)||!fits(Wide(i.c)*i.l+i.d)||!fits(Wide(i.c)*i.r+i.d))continue;
  unsigned ref=reference(i);assert(scalar(i)==ref);assert(avx2(i)==ref);v.push_back(i);
 }
 const I mx=std::numeric_limits<I>::max(),mn=std::numeric_limits<I>::min();
 for(auto i:std::vector<Input>{{mx,mn,1,-5,2,2},{mn,-1,-1,3,-1,-1},{mx,-mx,mn,mx,1,1},{0,mn,0,mx,mn,mx},{-1,0,0,-1,mn+1,mx}}){assert(fits(Wide(i.a)*i.l+i.b));assert(fits(Wide(i.a)*i.r+i.b));assert(fits(Wide(i.c)*i.l+i.d));assert(fits(Wide(i.c)*i.r+i.d));assert(scalar(i)==reference(i));assert(avx2(i)==reference(i));}
 return v;
}
int main(int argc,char**argv){
 std::string variant=argv[1];std::size_t n=std::stoull(argv[2]);unsigned reps=unsigned(std::stoul(argv[3]));auto data=make_input(n);U sum=0;auto begin=std::chrono::steady_clock::now();
 if(variant!="avx2")for(unsigned k=0;k<reps;++k)for(const auto&i:data)sum+=scalar(i);
 else for(unsigned k=0;k<reps;++k)for(const auto&i:data)sum+=avx2(i);
 auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count();
 std::printf("%" PRId64 " %" PRIu64 "\n",static_cast<std::int64_t>(ns),sum);
}
